let currentLanguage = document.documentElement.lang === "es" ? "es" : "en";
const focusRestoration = new WeakMap();

function translateElement(element, language) {
  const key = element.dataset.translate;
  if (key && Object.prototype.hasOwnProperty.call(translations[language], key)) {
    element.innerHTML = translations[language][key];
  }

  const ariaKey = element.dataset.ariaLabel;
  if (ariaKey && Object.prototype.hasOwnProperty.call(translations[language], ariaKey)) {
    element.setAttribute("aria-label", translations[language][ariaKey]);
  }
}

function setLanguage(language) {
  if (!translations[language]) return;
  currentLanguage = language;
  document.documentElement.lang = language;

  document.querySelectorAll("[data-translate], [data-aria-label]").forEach((element) => translateElement(element, language));
  document.querySelectorAll("[data-meta-key]").forEach((element) => {
    const key = element.dataset.metaKey;
    if (translations[language][key]) element.setAttribute("content", translations[language][key]);
  });

  document.title = translations[language]["page-title"];
  document.querySelectorAll(".lang-button").forEach((button) => {
    const active = button.dataset.lang === language;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  });

  const englishCv = "CV%20Francisco%20Javier%20Hern%C3%A1ndez%20Murillo%20English.pdf";
  const spanishCv = "CV%20Francisco%20Javier%20Hern%C3%A1ndez%20Murillo%20Spanish.pdf";
  const cvUrl = language === "es" ? spanishCv : englishCv;
  [document.getElementById("download-cv"), document.getElementById("footer-cv")].forEach((link) => {
    if (link) link.href = cvUrl;
  });
}

function getRollMessage(roll) {
  if (roll <= 5) return rollMessages[currentLanguage].low;
  if (roll <= 10) return rollMessages[currentLanguage].medium;
  if (roll <= 15) return rollMessages[currentLanguage].high;
  if (roll <= 19) return rollMessages[currentLanguage].veryHigh;
  return rollMessages[currentLanguage].critical;
}

function rollDice() {
  const result = document.getElementById("about-dice-result");
  if (!result) return;
  const roll = Math.floor(Math.random() * 20) + 1;
  result.innerHTML = translations[currentLanguage]["dice-roll-text"]
    .replace("{roll}", String(roll))
    .replace("{message}", getRollMessage(roll));
}

function focusableElements(container) {
  return [...container.querySelectorAll("a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex=\"-1\"])")]
    .filter((element) => element.offsetParent !== null || element === document.activeElement);
}

function closeProjectDialog(dialog) {
  if (!dialog) return;
  if (dialog.open) dialog.close();
  else dialog.removeAttribute("open");
  document.body.classList.remove("modal-open");
  const trigger = focusRestoration.get(dialog);
  if (trigger && document.contains(trigger)) trigger.focus();
}

function openProjectDialog(dialog, trigger) {
  if (!dialog) return;
  focusRestoration.set(dialog, trigger);
  document.body.classList.add("modal-open");
  if (typeof dialog.showModal === "function") dialog.showModal();
  else dialog.setAttribute("open", "");
  const closeButton = dialog.querySelector(".close-modal");
  if (closeButton) window.requestAnimationFrame(() => closeButton.focus());
}

function setupDialogs() {
  document.querySelectorAll(".project-card").forEach((card) => {
    const button = card.querySelector(".project-button");
    const dialog = document.getElementById(card.dataset.project);
    if (!button || !dialog) return;
    button.addEventListener("click", () => openProjectDialog(dialog, button));
  });

  document.querySelectorAll(".project-modal").forEach((dialog) => {
    dialog.querySelector(".close-modal")?.addEventListener("click", () => closeProjectDialog(dialog));
    dialog.addEventListener("cancel", (event) => {
      event.preventDefault();
      closeProjectDialog(dialog);
    });
    dialog.addEventListener("click", (event) => {
      if (event.target === dialog) closeProjectDialog(dialog);
    });
    dialog.addEventListener("close", () => {
      document.body.classList.remove("modal-open");
      const trigger = focusRestoration.get(dialog);
      if (trigger && document.contains(trigger)) trigger.focus();
    });
  });

  document.addEventListener("keydown", (event) => {
    const dialog = [...document.querySelectorAll(".project-modal")].find((item) => item.open);
    if (!dialog || event.key !== "Tab") return;
    const focusable = focusableElements(dialog);
    if (!focusable.length) return;
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  });
}

function setupMenu() {
  const toggle = document.querySelector(".menu-toggle");
  const panel = document.getElementById("primary-navigation");
  if (!toggle || !panel) return;

  const setMenuState = (open) => {
    panel.classList.toggle("is-open", open);
    toggle.setAttribute("aria-expanded", String(open));
    toggle.dataset.ariaLabel = open ? "menu-close" : "menu-open";
    const label = toggle.querySelector(".menu-label");
    if (label) {
      label.dataset.translate = open ? "menu-close" : "menu-open";
      label.innerHTML = translations[currentLanguage][label.dataset.translate];
    }
    toggle.setAttribute("aria-label", translations[currentLanguage][toggle.dataset.ariaLabel]);
  };

  toggle.addEventListener("click", () => setMenuState(!panel.classList.contains("is-open")));
  panel.querySelectorAll("a").forEach((link) => link.addEventListener("click", () => setMenuState(false)));
}

function setupNavigation() {
  const links = [...document.querySelectorAll(".nav-links a")];
  const sections = [...document.querySelectorAll("main section[id]")];
  const setActive = (id) => links.forEach((link) => {
    const active = link.dataset.section === id;
    link.classList.toggle("active", active);
    if (active) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });

  const updateActive = () => {
    const marker = window.scrollY + window.innerHeight * 0.35;
    let current = sections[0]?.id || "home";
    sections.forEach((section) => {
      if (section.offsetTop <= marker) current = section.id;
    });
    setActive(current);
  };

  window.addEventListener("scroll", updateActive, { passive: true });
  window.addEventListener("resize", updateActive, { passive: true });
  updateActive();
}

document.addEventListener("DOMContentLoaded", () => {
  document.body.classList.add("js-enabled");
  setLanguage(currentLanguage);
  document.querySelectorAll(".lang-button").forEach((button) => button.addEventListener("click", () => setLanguage(button.dataset.lang)));
  document.querySelector(".dice-button")?.addEventListener("click", rollDice);
  setupMenu();
  setupNavigation();
  setupDialogs();
});
